esbmc_test_source:
contract InvMutTest {
    C c;
    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    // We take an amount to attempt to withdraw. The call may revert.
    function run(uint256 amount) public payable {
        // No precondition on amount; address(this) must be able to receive Ether when withdraw succeeds.

        // Read observable before-values
        uint256 beforeContractBalance = address(c).balance;

        // Try the withdraw and observe whether it reverted and the contract balance after
        bool withdrewReverted;
        c.withdraw(amount); bool __rev0 = __ESBMC_reverted(); if (__rev0) {
            withdrewReverted = true;
        } else {
            withdrewReverted = false;
        }

        uint256 afterContractBalance = address(c).balance;

        // General rule: If withdraw succeeded (did not revert), then the contract's Ether balance decreased by at most the caller's recorded balance prior to the call.
        // We cannot read the private balances mapping, but withdraw's require ensures amount <= balances[msg.sender] when it succeeds.
        // Therefore, if withdraw succeeded, the contract's Ether balance must have decreased by at most amount (the withdrawn value), and amount was <= recorded balance.
        // We assert: if not reverted then beforeContractBalance >= afterContractBalance and (beforeContractBalance - afterContractBalance) <= amount
        // To avoid underflow in the assert, rephrase comparisons without subtraction.

        assert(
            withdrewReverted || (
                // contract balance did not increase
                afterContractBalance <= beforeContractBalance
                // and the decrease is at most amount: after >= before - amount  <=> after + amount >= before
                && (afterContractBalance + amount >= beforeContractBalance)
            )
        );
    }

    receive() external payable { }
}

